    private void chooseVoice(){
        if(controlsLocked||episode==null)return;
        ArrayList<Anime.Variant> rows=new ArrayList<>(SourceEngine.sortVariants(episode.variants));if(rows.isEmpty()){Ui.toast(this,"Для этой серии нет других озвучек");return;}
        String[] labels=new String[rows.size()];for(int i=0;i<rows.size();i++)labels[i]=rows.get(i).label();
        Anime.Episode selectedEpisode=episode;
        Ui.choices(this,"Озвучка",labels,index->{
            if(destroyed||episode!=selectedEpisode)return;Anime.Variant variant=rows.get(index);
            save(true);seekMs=nativeMode?(int)player.getCurrentPosition():browserTime*1000;
            requestedVoice=ApiRepository.voiceTitle(variant.name.isEmpty()?variant.label():variant.name);YoruApp.app().store.voicePreference(anime,requestedVoice);dubbing=requestedVoice;
            ArrayList<String> names=new ArrayList<>();int selected=buildVoiceGroups(episode,names);setup=true;voiceSelect.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));voiceSelect.setSelection(selected);setup=false;showVariant(variant);
        });
    }
