    private int buildVoiceGroups(Anime.Episode e,ArrayList<String> names){voiceGroups.clear();String preferred=dubbing==null||dubbing.isEmpty()?(requestedVoice.isEmpty()?YoruApp.app().store.voicePreference(anime):requestedVoice):dubbing;boolean strict=YoruApp.app().store.onlyPreferredVoice()&&!ApiRepository.voiceKey(preferred).isEmpty();int selected=buildVoiceGroupsInternal(e,names,preferred,strict);return selected;}
    private int buildVoiceGroupsInternal(Anime.Episode e,ArrayList<String> names,String preferred,boolean strict){voiceGroups.clear();LinkedHashMap<String,ArrayList<Anime.Variant>> map=new LinkedHashMap<>();for(Anime.Variant v:SourceEngine.sortVariants(e==null?null:e.variants)){if(v==null)continue;String raw=v.name+" "+v.displayName+" "+v.player;if(strict&&!ApiRepository.voiceMatches(preferred,raw))continue;String voice=ApiRepository.voiceTitle(v.name.isEmpty()?v.label():v.name);String key=ApiRepository.voiceKey(voice);if(key.isEmpty()){voice="Дорожка без названия";key="unknown:"+Integer.toHexString((v.url==null?"":v.url).hashCode());}ArrayList<Anime.Variant> group=map.get(key);if(group==null){group=new ArrayList<>();map.put(key,group);}group.add(v);}int selected=0,index=0;for(ArrayList<Anime.Variant> group:map.values()){voiceGroups.add(group);String voice=ApiRepository.voiceTitle(group.get(0).name);if(voice.isEmpty())voice="Дорожка без названия";names.add(voice);if(!preferred.isEmpty()&&ApiRepository.voiceMatches(preferred,voice))selected=index;index++;}return selected;}
