    private void renderNextEpisodes(){if(nextList==null)return;nextList.removeAllViews();if(playback==null||playback.video==null||episode==null)return;List<Anime.Episode> rows=playerEpisodes();int index=rows.indexOf(episode);if(index<0||index+1>=rows.size())return;LinearLayout head=Ui.row(this);head.addView(Ui.text(this,"Следующие серии",17,Ui.TEXT,true),new LinearLayout.LayoutParams(0,-2,1));TextView all=Ui.text(this,(rows.size()-index-1)+" дальше",10,Ui.PURPLE,true);head.addView(all);nextList.addView(head);Ui.space(nextList,10);for(int n=index+1;n<Math.min(rows.size(),index+5);n++){Anime.Episode e=rows.get(n);LinearLayout line=Ui.row(this);line.setGravity(Gravity.CENTER_VERTICAL);line.setPadding(Ui.dp(this,9),Ui.dp(this,8),Ui.dp(this,12),Ui.dp(this,8));line.setBackground(Ui.stroke(Ui.CARD,13,this));FrameLayout frame=new FrameLayout(this);frame.setBackground(Ui.shape(Ui.SURFACE,10,this));frame.setClipToOutline(true);ImageView img=new ImageView(this);img.setScaleType(ImageView.ScaleType.CENTER_CROP);frame.addView(img,new FrameLayout.LayoutParams(-1,-1));String poster=ApiRepository.safeUrl(e.poster);if(poster.isEmpty())poster=anime.poster;YoruApp.app().images.load(img,poster,anime.key()+":next:"+number(e.number));LinearLayout.LayoutParams fp=Ui.lp(this,70,42);fp.rightMargin=Ui.dp(this,10);line.addView(frame,fp);TextView text=Ui.text(this,(YoruApp.app().store.spoilerSafe()?"Серия "+number(e.number):e.label()),12,Ui.TEXT,true);text.setMaxLines(2);line.addView(text,new LinearLayout.LayoutParams(0,-2,1));Ui.Icon icon=new Ui.Icon(this,"play");icon.color=Ui.PURPLE;line.addView(icon,Ui.lp(this,22,22));final Anime.Episode target=e;line.setOnClickListener(v->{save(true);seekMs=resumeFor(target.number);loadEpisode(target);});Ui.press(line);nextList.addView(line,Ui.lp(this,-1,-2));Ui.space(nextList,7);}}
    private void move(int delta){if(offlineId!=null){Download next=YoruApp.app().downloads().neighbour(offlineDownload,delta);if(next!=null)loadOffline(next.request.id);else Ui.toast(this,"Следующая серия не скачана");return;}if(playback==null||playback.video==null||episode==null)return;int i=playerEpisodes().indexOf(episode)+delta;while(i>=0&&i<playerEpisodes().size()&&playerEpisodes().get(i).future)i+=delta>=0?1:-1;if(i>=0&&i<playerEpisodes().size()){save(true);seekMs=0;setup=true;episodeSelect.setSelection(i);setup=false;loadEpisode(playerEpisodes().get(i));}else if(delta>0)openNextQueued();}
